#include "mounted_model_material_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("MDL and loose mount required");std::ifstream file(argv[1],std::ios::binary);if(!file)throw std::runtime_error("MDL missing");std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(file)),{});auto metadata=readModelMaterialMetadataCandidate(bytes);size_t count=0;for(size_t slot=0;slot<metadata.skins.at(0).size();++slot){auto material=resolveMountedModelMaterialCandidate(metadata,0,int32_t(slot),{argv[2]});if(vmtAsciiLowerCandidate(material.syntax.key)!="vertexlitgeneric")throw std::runtime_error("shader fixture mismatch");std::cout<<metadata.resolve(0,int32_t(slot))<<" -> "<<material.baseTexture.string()<<'\n';++count;}size_t rejected=0;for(auto name:{"../outside","models/../../outside","C:/outside","/outside"}){try{materialRelativePathCandidate(name,".vtf");}catch(const std::runtime_error&){++rejected;}}if(count!=7||rejected!=4)throw std::runtime_error("material resolution checks failed");std::cout<<"Mounted material resolution passed count="<<count<<" rejected="<<rejected<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
